with flagged as (select *, case when reading_ts - lag(reading_ts) over (partition by device_code order by reading_ts, id) > interval '45' minute then 1 else 0 end as is_new_burst from device_readings), islands as (select id, device_code, reading_ts, status_bits, firmware, sum(is_new_burst) over (partition by device_code order by reading_ts, id rows between unbounded preceding and current row) as session_no from flagged) select id, reading_ts, firmware, session_no from islands order by id desc nulls first;
